public class Main {
    // 简化的 execution 切点匹配器（纯 JDK，不依赖 AspectJ）
    static class Pointcut {
        String ret, pkg, cls, method, args;
        static Pointcut parse(String expr) {
            String body = expr.trim();
            if (body.startsWith("execution(")) body = body.substring("execution(".length());
            if (body.endsWith(")")) body = body.substring(0, body.length() - 1);
            body = body.trim();
            Pointcut p = new Pointcut();
            String[] parts = body.split("\\s+");
            p.ret = parts[0];
            String sig = parts[1];
            int lp = sig.indexOf('(');
            String full = sig.substring(0, lp);
            p.args = sig.substring(lp);
            int lastDot = full.lastIndexOf('.');
            String clzPart = full.substring(0, lastDot);
            p.method = full.substring(lastDot + 1);
            int lastDot2 = clzPart.lastIndexOf('.');
            p.pkg = clzPart.substring(0, lastDot2);
            p.cls = clzPart.substring(lastDot2 + 1);
            return p;
        }
        boolean matches(String retType, String fullClass, String m, int argCount) {
            if (!("*".equals(ret) || ret.equals(retType))) return false;
            if (!pMatch(pkg, fullClass)) return false;
            if (!("*".equals(cls) || cls.equals(className(fullClass)))) return false;
            if (!("*".equals(method) || method.equals(m) || matchPrefix(method, m))) return false;
            return argsMatch(args, argCount);
        }
        boolean pMatch(String patPkg, String fullClass) {
            int li = fullClass.lastIndexOf('.');
            String fcp = li < 0 ? "" : fullClass.substring(0, li);
            if ("*".equals(patPkg)) return true;
            if (patPkg.endsWith(".*")) return fcp.equals(patPkg.substring(0, patPkg.length() - 2));
            return patPkg.equals(fcp);
        }
        String className(String fc) { int li = fc.lastIndexOf('.'); return li < 0 ? fc : fc.substring(li + 1); }
        boolean matchPrefix(String pat, String m) {
            return pat.endsWith("*") && m.startsWith(pat.substring(0, pat.length() - 1));
        }
        boolean argsMatch(String a, int n) {
            if ("(*)".equals(a) || "(..)".equals(a)) return true;
            if ("()".equals(a)) return n == 0;
            String inner = a.substring(1, a.length() - 1);
            int cnt = inner.isEmpty() ? 0 : inner.split(",").length;
            return cnt == n;
        }
    }
    public static void main(String[] a) {
        Pointcut p = Pointcut.parse("execution(* com.demo.*.*(..))");
        System.out.println("match UserService.save: " + p.matches("void", "com.demo.UserService", "save", 1));
        System.out.println("match Order.place: " + p.matches("void", "com.demo.Order", "place", 2));
        System.out.println("non-match Other.foo: " + p.matches("void", "com.other.Other", "foo", 0));
        Pointcut p2 = Pointcut.parse("execution(* com.demo.UserService.save*(..))");
        System.out.println("prefix save* on saveOrder: " + p2.matches("void", "com.demo.UserService", "saveOrder", 1));
        System.out.println("prefix save* on delete: " + p2.matches("void", "com.demo.UserService", "delete", 1));
        Pointcut p3 = Pointcut.parse("execution(int com.demo.*.calc(int))");
        System.out.println("exact calc(int)->int: " + p3.matches("int", "com.demo.Mathx", "calc", 1));
    }
}
